class Solution {
    public boolean areAlmostEqual(String s1,String s2){
        int first=-1,second=-1;
        for(int i=0;i<s1.length();i++)if(s1.charAt(i)!=s2.charAt(i)){
            if(first<0)first=i;
            else if(second<0)second=i;
            else return false;
        }
        return first<0||second>=0&&s1.charAt(first)==s2.charAt(second)&&s1.charAt(second)==s2.charAt(first);
    }
}

code.kotlin:
class Solution {
    fun areAlmostEqual(s1:String,s2:String):Boolean{
        val mismatch=s1.indices.filter{
            s1[it]!=s2[it]
        };
        return mismatch.isEmpty()||mismatch.size==2&&s1[mismatch[0]]==s2[mismatch[1]]&&s1[mismatch[1]]==s2[mismatch[0]]
    }
}

